def tbl(heads, rows):
    A('<div class="table-responsive"><table><tbody><tr>'+''.join('<th>'+h+'</th>' for h in heads)+'</tr>')
    for r in rows: A('<tr>'+''.join('<td>'+c+'</td>' for c in r)+'</tr>')
    A('</tbody></table></div>')

